package com.tpverp.backend.pdawork;
import static org.assertj.core.api.Assertions.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;import org.junit.jupiter.api.Test;
class PdaStockLotTest{@Test void consumesTrackedLotAndRejectsConcurrentOrExcessQuantity(){var actor=UUID.randomUUID();var lot=new PdaStockLot(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"CAFE","L-01",LocalDate.of(2026,9,1),UUID.randomUUID(),"ALB-1",new BigDecimal("5"),Instant.now(),actor);lot.consume(new BigDecimal("2"),0,Instant.now(),actor);assertThat(lot.getQuantity()).isEqualByComparingTo("3");assertThat(lot.getLastConsumedBy()).isEqualTo(actor);assertThatThrownBy(()->lot.consume(BigDecimal.ONE,1,Instant.now(),actor)).isInstanceOf(PdaWorkConflictException.class);assertThatThrownBy(()->lot.consume(new BigDecimal("4"),0,Instant.now(),actor)).hasMessageContaining("insuficiente");}}
